construct_upper_hull <- function(x, h, hp, domain) {
  # Construct piecewise linear upper hull
  # Returns intersection points (z) and coefficients

  n <- length(x)
  z <- numeric(n + 1)
  z[1] <- domain[1]
  z[n + 1] <- domain[2]

  # Compute intersection points
  eps_parallel <- 1e-10  # Threshold for detecting nearly parallel tangent lines
  for (i in 2:n) {
    denom <- hp[i-1] - hp[i]
    if (abs(denom) < eps_parallel) {
      # Tangent lines are nearly parallel - use midpoint as intersection
      # This handles cases like exponential distribution with constant derivative
      z[i] <- (x[i-1] + x[i]) / 2
    } else {
      z[i] <- (h[i] - h[i-1] - x[i]*hp[i] + x[i-1]*hp[i-1]) / denom
    }
  }

  # Validate z ordering to prevent invalid hull geometry
  for (i in 1:n) {
    if (z[i] >= z[i+1]) {
      stop(sprintf("Invalid upper hull: intersection points not properly ordered (z[%d]=%.6f >= z[%d]=%.6f). This indicates numerical precision issues or invalid function.", 
                   i, z[i], i+1, z[i+1]))
    }
  }

  return(list(z = z, x = x, h = h, hp = hp))
}

