if (abs(hp[segment]) < 1e-10) {
  # Uniform sampling for flat segment
  x_star <- runif(1, z_left, z_right)
} else {
  # Exponential sampling with numerical stability
  # Sample from exp(h + hp*(x - x[segment])) on [z_left, z_right]
  # Using log-space arithmetic to avoid overflow
  u <- runif(1)
  delta_z <- z_right - z_left
  hp_delta <- hp[segment] * delta_z

  # Compute log(1 + u * (exp(hp_delta) - 1)) stably
  # Using log1p and expm1 for numerical precision
  if (abs(hp_delta) > 30) {
    # For large |hp_delta|, use asymptotic approximation
    if (hp_delta > 0) {
      # exp(hp_delta) >> 1, so log(1 + u*(exp(hp_delta)-1)) ≈ log(u) + hp_delta
      log_term <- log(u) + hp_delta
    } else {
      # exp(hp_delta) ≈ 0, so log(1 + u*(exp(hp_delta)-1)) ≈ log(1 - u)
      log_term <- log1p(-u + u * exp(hp_delta))
    }
  } else {
    # General case: use log1p(u * expm1(hp_delta))
    log_term <- log1p(u * expm1(hp_delta))
  }

  x_star <- z_left + log_term / hp[segment]
}

